$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; elif test -f README.json; then cat README.json >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert");
const file=".devcontainer/devcontainer.json";
const prior=JSON.parse(fs.readFileSync(file,"utf8"));
assert(!Object.hasOwn(prior,"postStartCommand"),"Existing startup hook must not be overwritten");
assert(prior.postCreateCommand==="npm install -g @modelcontextprotocol/server-everything","Unexpected setup command");
assert(JSON.stringify(prior.forwardPorts)==="[3000]","Unexpected forwarded port");
const updated={...prior};
updated.postStartCommand="nohup bash -lc 'PORT=3000 npx @modelcontextprotocol/server-everything streamableHttp' > /tmp/mcp-everything.log 2>&1 < /dev/null &";
const {postStartCommand,...rest}=updated;
assert.deepStrictEqual(rest,prior,"Other configuration changed");
fs.writeFileSync(file,JSON.stringify(updated,null,2)+"\n");
const check=JSON.parse(fs.readFileSync(file,"utf8"));
assert.deepStrictEqual(check,updated);
const cp=require("child_process");
cp.execFileSync("bash",["-n","-c",updated.postStartCommand]);
assert(updated.postStartCommand.includes("PORT=3000"));
assert(updated.postStartCommand.includes("streamableHttp"));
console.log("UPDATED",file);
console.log("POST_START_COMMAND",updated.postStartCommand);
console.log("UNCHANGED_FIELDS",Object.keys(rest).join(","));
console.log("BASH_SYNTAX_VALID",true);
console.log("VALID_JSON",true);
console.log("NO_RUNTIME_CLAIM",true);
NODE
git add -- .devcontainer/devcontainer.json
git diff --cached --check
git diff --cached -- .devcontainer/devcontainer.json
git commit -m 'Auto-start Everything MCP Streamable HTTP server in Codespaces'
for i in 1 2 3 4; do
  git fetch origin main -q
  git rebase origin/main -q
  if git push origin HEAD:main; then break; fi
  test "$i" -lt 4
done
printf 'PUBLISHED_COMMIT ';git rev-parse HEAD
git show --stat --oneline HEAD
